// Validate input from claude.ai chat — v3: authed-malformed -> discard silencioso (sem throw/alerta)
const SECRET = '3NuJfuJsMUFGonDnPESfiO5H5aLVBu1cqKl_-YcXS0c';
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};
const staticData = $getWorkflowStaticData('global');

// Healthcheck/ping — inalterado
if (body && body.ping !== undefined && Object.keys(body).length === 1) return [];

// validacao de FORMA minima (sem throw)
const validTypes = ['Decision','Learning','Error','Insight','Pattern','Fact','Drift'];
const validProjects = ['TJ','TM','CL','CF','Ops','Personal'];
const required = ['summary','details','type','importance','project'];
const importance = parseInt(body.importance);
const shapeOk =
  required.every(f => body[f] !== undefined && body[f] !== null && body[f] !== '') &&
  validTypes.includes(body.type) &&
  validProjects.includes(body.project) &&
  !isNaN(importance) && importance >= 1 && importance <= 5;

const authOk = headers['x-webhook-secret'] === SECRET;

let tags = body.tags;
if (!Array.isArray(tags)) tags = tags ? [String(tags)] : [];
tags = tags.filter(t => t && typeof t === 'string').map(t => t.trim()).filter(Boolean);

const clean = shapeOk ? {
  summary: String(body.summary).trim(),
  details: String(body.details).trim(),
  type: body.type, importance, project: body.project, tags, source: 'ClaudeAi'
} : null;

// roteamento
if (authOk && shapeOk)  return [{ json: { _route: 'write', ...clean } }];
if (!authOk && shapeOk) return [{ json: { _route: 'dlq', _reason: 'missing_auth', _payload: body } }];
if (authOk && !shapeOk) {
  // decisao (b) v3: autenticado mas mal-formado -> descarta em silencio (sem throw, sem Telegram).
  // Historico: so disparava com testes manuais do proprio Ary. Conta para auditoria via staticData.
  staticData.malformedCount = (staticData.malformedCount || 0) + 1;
  return [{ json: { _route: 'discard', _reason: 'authed_malformed', _malformedCount: staticData.malformedCount } }];
}
// !authOk && !shapeOk -> descarta com contador
staticData.discardCount = (staticData.discardCount || 0) + 1;
return [{ json: { _route: 'discard', _discardCount: staticData.discardCount } }];

const mem = $('Validate Input').item.json;
const embedding = $json.data[0].embedding;
return [{ json: { ...mem, embedding } }];

// v2 — trata output do Find Similar via Code (objecto {action,...}), NÃO array
const upstream = $input.first().json;
const prev = $('Merge Embedding').item.json;

if (upstream.action === 'update' && upstream.existingId) {
  return [{ json: { action: 'update', existingId: upstream.existingId, similarity: upstream.similarity, ...prev } }];
}
return [{ json: { action: 'insert', ...prev } }];

const result = $input.first().json;
const upstream = $('Decide Upsert').item.json;
const row = Array.isArray(result) ? result[0] : result;

// Para UPDATE, o body de resposta pode não conter id (Prefer: return=minimal),
// mas existingId do upstream tem-o.
const responseId = upstream.action === 'update'
  ? (upstream.existingId || row?.id || null)
  : (row?.id || null);

return [{
  json: {
    success: true,
    action: upstream.action,
    id: responseId,
    summary: upstream.summary,
    project: upstream.project,
    source: 'ClaudeAi',
    similarity: upstream.similarity || null
  }
}];

const item = $input.first().json;

const body = JSON.stringify({
  query_embedding: item.embedding,
  similarity_threshold: 0.92,
  filter_project: item.project
});

const SUPABASE_KEY = '***REDACTED***';

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://apfngqcnjdfinqwefzcs.supabase.co/rest/v1/rpc/find_similar_memory',
  headers: {
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${SUPABASE_KEY}`,
    'Content-Type': 'application/json'
  },
  body: body,
  json: true,
  returnFullResponse: false
});

const similarResults = Array.isArray(response) ? response : [];
const hasSimilar = similarResults.length > 0 && similarResults[0]?.id;

if (hasSimilar) {
  return [{ json: { action: 'update', existingId: similarResults[0].id, similarity: similarResults[0].similarity, ...item } }];
} else {
  return [{ json: { action: 'insert', ...item } }];
}

